/**
 * Fast perceptual color distance in CIELAB space (CIE76 / Delta E)
 */
export function deltaE(l1: number, a1: number, b1: number, l2: number, a2: number, b2: number): number {
  const dl = l1 - l2;
  const da = a1 - a2;
  const db = b1 - b2;
  return Math.sqrt(dl * dl + da * da + db * db);
}

/**
 * Convert RGB to CIELAB coordinates
 */
export function rgbToLab(r: number, g: number, b: number): [number, number, number] {
  let rLin = r / 255.0;
  let gLin = g / 255.0;
  let bLin = b / 255.0;

  rLin = rLin > 0.04045 ? Math.pow((rLin + 0.055) / 1.055, 2.4) : rLin / 12.92;
  gLin = gLin > 0.04045 ? Math.pow((gLin + 0.055) / 1.055, 2.4) : gLin / 12.92;
  bLin = bLin > 0.04045 ? Math.pow((bLin + 0.055) / 1.055, 2.4) : bLin / 12.92;

  const x = (rLin * 0.4124 + gLin * 0.3576 + bLin * 0.1805) / 0.95047;
  const y = (rLin * 0.2126 + gLin * 0.7152 + bLin * 0.0722) / 1.00000;
  const z = (rLin * 0.0193 + gLin * 0.1192 + bLin * 0.9505) / 1.08883;

  const fx = x > 0.008856 ? Math.cbrt(x) : 7.787 * x + 16.0 / 116.0;
  const fy = y > 0.008856 ? Math.cbrt(y) : 7.787 * y + 16.0 / 116.0;
  const fz = z > 0.008856 ? Math.cbrt(z) : 7.787 * z + 16.0 / 116.0;

  const L = 116.0 * fy - 16.0;
  const A = 500.0 * (fx - fy);
  const B = 200.0 * (fy - fz);

  return [L, A, B];
}

/**
 * Find closest thread in catalog using CIELAB Delta E (perceptually uniform)
 */
export function findClosestThread(
  r: number,
  g: number,
  b: number,
  preferredBrand?: 'DMC' | 'Anchor' | 'Ariadna' | 'Madeira' | 'CXC' | 'Dimensions'
): ThreadDef {
  const brandFiltered = preferredBrand
    ? THREAD_CATALOG.filter((t) => t.brand === preferredBrand)
    : THREAD_CATALOG;

  const list = brandFiltered.length > 0 ? brandFiltered : THREAD_CATALOG;
  const [targetL, targetA, targetB] = rgbToLab(r, g, b);

  let bestThread = list[0];
  let minDistance = Infinity;

  for (let i = 0; i < list.length; i++) {
    const t = list[i];
    const tL = t.l ?? 50;
    const tA = t.a ?? 0;
    const tB = t.b_val ?? 0;

    const dL = targetL - tL;
    const dA = targetA - tA;
    const dB = targetB - tB;
    const dist = dL * dL + dA * dA + dB * dB;

    if (dist < minDistance) {
      minDistance = dist;
      bestThread = t;
    }
  }

  return bestThread;
}
